-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 5.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module5.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"badGood":{"label":"what to assert after a save","bad":"~~~ts\nawait page.getByRole('button', { name: 'Save' }).click();\n// Proves the button exists after clicking — not that anything was saved.\nawait expect(page.getByRole('button', { name: 'Save' })).toBeVisible();\n~~~","good":"~~~ts\nawait page.getByRole('button', { name: 'Save' }).click();\n// Proves the save produced the outcome the user expects.\nawait expect(page.getByRole('alert')).toHaveText('Changes saved');\nawait expect(page.getByRole('row', { name: /Priya Patel/ })).toBeVisible();\n~~~"},"davidTip":"When you finish a test, read only its assertions, ignoring the setup. If the assertions alone do not tell you what the feature is supposed to do, the test is not testing behaviour — it is going through motions. Good assertions read like a specification.","visualAid":{"type":"comparison","title":"Where an assertion can be aimed","headers":["Assertion aims at","Example","Fails on real breakage?","Survives a refactor?"],"rows":[["User-visible outcome","Confirmation text, updated total, new URL","Yes","Yes"],["Observable behaviour","Button enables when form is valid","Yes","Yes"],["DOM structure / CSS class",".dashboard-shell is visible","Often no","Often no"],["Internal mechanism","A specific network call fired","Sometimes","No"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A team proudly reported eighty per cent of critical routes \"covered\" by end-to-end tests, all green in every pipeline. During an incident review after a checkout outage that had shipped unnoticed, someone opened the checkout test: it navigated to the page and asserted the page title was present. The title rendered on the error page too, so the test had stayed green throughout the outage. The route was counted as covered; it was never tested. The team introduced a rule that every route test must assert a feature-specific outcome, and re-audited the rest — a third of them were the same shape.","badGood":{"label":"search results assertion","bad":"~~~ts\nawait page.getByRole('searchbox').fill('keyboard');\nawait page.getByRole('button', { name: 'Search' }).click();\n// Passes even if zero, wrong, or unrelated results come back.\nawait expect(page.getByRole('list')).toBeVisible();\n~~~","good":"~~~ts\nawait page.getByRole('searchbox').fill('keyboard');\nawait page.getByRole('button', { name: 'Search' }).click();\nawait expect(page.getByRole('heading', { name: /results for \"keyboard\"/i })).toBeVisible();\nawait expect(page.getByRole('listitem')).not.toHaveCount(0);\nawait expect(page.getByRole('listitem').first()).toContainText(/keyboard/i);\n~~~"},"miniChallenge":"Pick one weak test and apply the \"mutation\" check: on a throwaway branch, break the feature it covers and run the test. If it stays green, keep adding specific assertions until the broken feature makes it red — then throw the branch away and keep the stronger test."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"badGood":{"label":"choosing which values to automate","bad":"~~~ts\n// Six tests, all from the same in-range partition — no boundaries, no negatives.\nfor (const qty of ['2', '3', '4', '5', '6', '7']) {\n  test(`adds ${qty} to basket`, async ({ page }) => {\n    await page.goto('/products/keyboard');\n    await page.getByLabel('Quantity').fill(qty);\n    await page.getByRole('button', { name: 'Add to basket' }).click();\n    await expect(page.getByRole('status')).toContainText('added');\n  });\n}\n~~~","good":"~~~ts\n// Four tests on the boundaries and beyond — happy and negative paths, each asserting the exact outcome.\nfor (const { qty, valid } of [\n  { qty: '0', valid: false }, { qty: '1', valid: true },\n  { qty: '10', valid: true }, { qty: '11', valid: false },\n]) {\n  test(`quantity ${qty} is ${valid ? 'accepted' : 'rejected'}`, async ({ page }) => {\n    await page.goto('/products/keyboard');\n    await page.getByLabel('Quantity').fill(qty);\n    await page.getByRole('button', { name: 'Add to basket' }).click();\n    await expect(page.getByRole(valid ? 'status' : 'alert')).toBeVisible();\n  });\n}\n~~~"},"visualAid":{"type":"comparison","title":"Designing cases for a 1–10 quantity field","headers":["Value","Partition","Why it earns a test"],"rows":[["0","Below range (invalid)","Boundary neighbour; checks the lower guard"],["1","In range (valid)","Lower boundary; classic off-by-one site"],["10","In range (valid)","Upper boundary; is it inclusive?"],["11","Above range (invalid)","Boundary neighbour; checks the upper guard"],["5","In range (valid)","Redundant — same partition as 1 and 10"]]},"davidTip":"When someone says \"let's test lots of values to be thorough\", ask which partition each value belongs to. Thoroughness is covering every partition and boundary once, not covering one partition fifty times. The second kind of thorough just makes your suite slower."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team had a single \"smoke test\" that walked through sign-up, onboarding, a first purchase and a settings change in one long script. It failed roughly once a week, always somewhere different, and each failure took an engineer half a morning to diagnose because the red was never where the real fault was — an early step's flake hid everything after it. The suite was quietly set to \"continue on failure\" and then, inevitably, ignored. Splitting that one test into a dozen focused ones meant each failure named its own behaviour, triage dropped to minutes, and the team started trusting the smoke suite again.","badGood":{"label":"focus and reason to fail","bad":"~~~ts\ntest('user flow', async ({ page }) => {\n  // logs in, searches, adds to basket, checks out, and updates profile —\n  // when it fails, which one broke?\n});\n~~~","good":"~~~ts\ntest('a valid user can log in', async ({ page }) => { /* one behaviour */ });\ntest('search returns matching products', async ({ page }) => { /* one behaviour */ });\ntest('adding an item updates the basket count', async ({ page }) => { /* one behaviour */ });\n~~~"},"miniChallenge":"Take your longest test and count the distinct behaviours it checks. Split it into that many tests, each named for its behaviour, and confirm that breaking any one feature now turns exactly one test red.","visualAid":{"type":"flow","title":"The Arrange-Act-Assert shape of a focused test","steps":["Arrange — put the app in the state the behaviour needs","Act — perform the single action under test","Assert — check the outcome of that one action","Stop — resist adding a second act; that is a second test"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"badGood":{"label":"test naming","bad":"~~~ts\ntest('test1', async ({ page }) => { /* ... */ });\ntest('checkout2', async ({ page }) => { /* ... */ });\ntest('err', async ({ page }) => { /* ... */ });\n~~~","good":"~~~ts\ntest('a valid card completes the purchase and shows a receipt', async ({ page }) => { /* ... */ });\ntest('an expired card is declined with a clear message', async ({ page }) => { /* ... */ });\ntest('an empty basket cannot reach the payment step', async ({ page }) => { /* ... */ });\n~~~"},"davidTip":"Write the test name before the test body. If you cannot state the behaviour in one plain sentence, you do not yet know what you are testing — and the code you write next will wander. The name is a design tool, not a label you slap on at the end.","miniChallenge":"Pick a feature and, without opening the application, try to describe what it does using only your test names. Wherever you get stuck, the name that failed you is the one to rewrite."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team encoded every tier of a complex pricing engine — dozens of discount and tax permutations — as end-to-end Playwright tests, because that was the tool they knew. The UI suite grew to over an hour, flaked constantly on unrelated front-end changes, and engineers took to re-running it until it went green. When they finally moved the pricing permutations into fast unit tests and cut the UI layer to a handful of journeys that proved the number reached the customer, the pipeline dropped to minutes and the flakiness that had trained everyone to ignore red results disappeared. The evidence got faster and more trustworthy by having fewer UI tests, not more.","visualAid":{"type":"comparison","title":"Choosing the cheapest reliable level for a risk","headers":["Risk to cover","Cheapest reliable level","What the UI test (if any) should assert"],"rows":[["Discount / tax calculation boundaries","Unit test","Only that the trusted total is displayed"],["Field validation rules and error codes","API / integration test","That an error is shown to the user"],["Service contract between front and back end","API test","That the page renders the response"],["Critical end-to-end journey (buy, confirm)","UI test","The whole integrated outcome a user sees"]]},"davidTip":"Before writing a UI test, try to make it fail for a reason that has nothing to do with the browser. If you can — because it is really checking logic or a contract — that check belongs lower down. Reserve the UI tier for tests that could only fail because something a user actually sees is broken.","miniChallenge":"Audit your suite's shape: count tests per level. If the UI tier is not the smallest, pick the single highest-value logic check currently done at the UI and rewrite it as a unit or API test, then delete or slim the UI version."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 5 and l.lesson_number = 6;

